<?php require_once __DIR__.'/_common.php';$jadwal=[];if($daftarLansia){$ids=array_values(array_unique(array_map('intval',array_column($daftarLansia,'id_posyandu'))));$m=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT j.*,p.nama_posyandu FROM jadwal_posyandu j JOIN posyandu p ON p.id_posyandu=j.id_posyandu WHERE j.id_posyandu IN ($m) ORDER BY j.tanggal DESC,j.jam_mulai DESC");$s->execute($ids);$jadwal=$s->fetchAll();}awal_halaman('Jadwal Posyandu','jadwal'); ?>
<section class="f-intro"><h1>Jadwal Kegiatan Posyandu</h1><p>Agenda pemeriksaan rutin, senam lansia, penyuluhan, dan kegiatan lain dari Posyandu yang terhubung dengan profil lansia keluarga Anda.</p></section><section class="f-card"><h3>Daftar Jadwal Posyandu</h3>
<?php if($jadwal):foreach($jadwal as $j):$ts=strtotime($j['tanggal']);?><div class="f-schedule"><div class="f-date"><b><?=date('d',$ts)?></b><small><?=strtoupper(date('M',$ts))?></small></div><div style="flex:1;min-width:0"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><strong style="font-size:13px;color:#253b4a"><?=h($j['judul'])?></strong><span class="f-badge <?=warna_status($j['status'])?>"><?=h(ucfirst($j['status']))?></span></div><div style="font-size:11px;color:#6e7d89;margin-top:6px"><?=h($j['jenis_kegiatan'])?> · <?=tgl_id($j['tanggal'])?></div><div style="font-size:11px;color:#6e7d89;margin-top:4px"><?=jam_id($j['jam_mulai'])?><?= $j['jam_selesai']?' - '.jam_id($j['jam_selesai']):''?> WIB · <?=h($j['lokasi'])?></div><div style="font-size:11px;color:#6e7d89;margin-top:4px"><?=h($j['nama_posyandu'])?></div><?php if($j['deskripsi']):?><p style="font-size:11px;line-height:1.6;color:#526272;margin:8px 0 0"><?=nl2br(h($j['deskripsi']))?></p><?php endif;?></div></div><?php endforeach;else:?><div class="f-empty">Belum ada jadwal Posyandu yang dapat ditampilkan. Pastikan profil lansia sudah terhubung dengan unit Posyandu.</div><?php endif;?></section><?php akhir_halaman(); ?>
